   19	// The one surviving situation for invariant:NAKED_BESIDE_WALLED after the QUAL-DEDUP merge: a naked
   20	// colony, a naked planet and a stationary fleet, each read at the bound and at zero. The live cohort
   21	// read found accounts with planets at zero defence while a sibling held a real wall: the whole wall
   22	// was raised on the planet with the most to lose and the bare siblings were never reached. One login
   23	// has to give the bare planet the wall order the account already holds elsewhere, in the host's own
   24	// yard.
   25	test('a login gives the bare sibling the wall the account already holds elsewhere', function (): void {
   26	    $situation = Situation::of($this)
   27	        ->levelEveryPlanet('robot_factory', 2)
   28	        ->levelEveryPlanet('shipyard', 4)
   29	        ->defence('rocket_launcher', 20)
   30	        ->stockEveryPlanet(20_000_000, 10_000_000, 5_000_000)
   31	        ->session();
   32	
   33	    $bare = Planet::query()->where('user_id', $this->currentUserId)->where('planet_type', 1)
   34	        ->whereKeyNot($this->currentPlanetId)->value('id');
   35	    $planet = app(PlanetServiceFactory::class)->make((int) $bare, true);
   36	
   37	    $situation->expectWork(AiWorkKind::QueueUnits);
