   40	    // intent, so the wall counts whether it is standing or still paid for in the yard.
   41	    expect(app(DefenseNeedEvaluator::class)->standingUnits($planet))->toBeGreaterThan(0, 'expected the wall on the bare sibling; ' . $situation->account());
   42	});
