256	/** @return list<int> the account's planets (moons excluded) whose built defence columns are all zero */
257	function builtNakedPlanets(int $playerId): array
258	{
259	    $defence = array_map(static fn ($object): string => $object->machine_name, ObjectService::getDefenseObjects());
260	
261	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
262	        ->map(static fn ($id): int => (int) $id)
263	        ->filter(static function (int $id) use ($defence): bool {
264	            $row = (array) DB::table('planets')->where('id', $id)->first();
265	            foreach ($defence as $machineName) {
266	                if ((int) ($row[$machineName] ?? 0) > 0) {
267	                    return false;
268	                }
269	            }
270	
271	            return true;
272	        })->values()->all();
273	}
274	
275	/** @return list<int> the account's planets (moons excluded) that hold no defence, ordered or built */
276	function nakedPlanets(int $playerId): array
277	{
278	    return Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id')
279	        ->map(static fn ($id): int => (int) $id)
280	        ->filter(static function (int $id): bool {
281	            $planet = app(PlanetServiceFactory::class)->make($id, true);
282	
283	            return $planet === null || app(DefenseNeedEvaluator::class)->standingUnits($planet) === 0;
284	        })->values()->all();
285	}
