287	/** The defence units the account stands on its planets. */
288	function standingDefence(int $playerId): int
289	{
290	    $total = 0;
291	
292	    foreach (Planet::query()->where('user_id', $playerId)->where('planet_type', 1)->pluck('id') as $planetId) {
293	        $planet = app(PlanetServiceFactory::class)->make((int) $planetId, true);
294	        $total += $planet === null ? 0 : $planet->getDefenseUnits()->getAmount();
295	    }
296	
297	    return $total;
298	}

